/// The whole of one Festival Quest adventure, as data.
///
/// An adventure is content, not code: three locations, four characters, a
/// market, a mystery, a courtyard to prepare and two endings. The engine can
/// play any adventure that satisfies [AdventureValidator], whether it was
/// written by hand (`kPongalAdventure`) or generated by Gemini and checked
/// before anybody saw it.
///
/// Everything here serialises, because a generated adventure is saved to the
/// device and replayed offline.
library;

import 'dart:convert';

import 'package:flutter/material.dart';

import 'adventure_icons.dart';
import 'requirement.dart';

/// Where an adventure came from. Shown to the player, because "made for you
/// just now" and "the one that ships with the app" are different things and
/// they should know which they are playing.
enum AdventureSource {
  bundled('The adventure that comes with MindPal'),
  generated('Made for you by MindPal');

  const AdventureSource(this.label);
  final String label;

  static AdventureSource fromName(String? name) => AdventureSource.values
      .firstWhere((value) => value.name == name, orElse: () => bundled);
}

/// What an interactive point on a scene is for.
enum HotspotKind {
  /// Someone to talk to.
  character,

  /// Something to look at, and perhaps pick up.
  object,

  /// A way to another location.
  exit,

  /// Opens the market stalls.
  market,

  /// Opens the "where was it?" screen of the mystery.
  accuse,

  /// Opens the courtyard preparation.
  prepare,
}

/// A tappable point in a scene.
class Hotspot {
  const Hotspot({
    required this.id,
    required this.label,
    required this.kind,
    required this.x,
    required this.y,
    this.targetId,
    this.icon = Icons.help_outline_rounded,
    this.color = const Color(0xFF00695C),
    this.visibleWhen = Requirement.none,
    this.inspectText,
    this.onInspect = Effect.none,
    this.repeatable = true,
  });

  final String id;

  /// Always drawn under the picture. Nothing in this game is a guess-the-icon
  /// puzzle.
  final String label;

  final HotspotKind kind;

  /// Position within the scene, 0..1 of width and height. Fractions rather
  /// than pixels so one scene lays out on any screen without a second design.
  final double x;
  final double y;

  /// The character, item or location this points at, depending on [kind].
  final String? targetId;

  final IconData icon;
  final Color color;

  /// Hidden until this holds. A hotspot the player cannot yet use is absent
  /// rather than greyed out — a dead control invites tapping.
  final Requirement visibleWhen;

  /// Shown when an object is tapped, before its effect applies.
  final String? inspectText;

  final Effect onInspect;

  /// False for a one-shot: once its effect has run it disappears. Used for
  /// objects that are picked up.
  final bool repeatable;

  Map<String, dynamic> toMap() => {
    'id': id,
    'label': label,
    'kind': kind.name,
    'x': x,
    'y': y,
    if (targetId != null) 'targetId': targetId,
    'icon': adventureIconName(icon),
    'color': color.toARGB32(),
    if (!visibleWhen.isAlwaysMet) 'visibleWhen': visibleWhen.toMap(),
    if (inspectText != null) 'inspectText': inspectText,
    if (!onInspect.isEmpty) 'onInspect': onInspect.toMap(),
    'repeatable': repeatable,
  };

  factory Hotspot.fromMap(Map<String, dynamic> map) => Hotspot(
    id: map['id'] as String? ?? '',
    label: map['label'] as String? ?? '',
    kind: HotspotKind.values.firstWhere(
      (value) => value.name == map['kind'],
      orElse: () => HotspotKind.object,
    ),
    x: (map['x'] as num?)?.toDouble() ?? 0.5,
    y: (map['y'] as num?)?.toDouble() ?? 0.5,
    targetId: map['targetId'] as String?,
    icon: adventureIcon(map['icon'] as String?),
    color: Color((map['color'] as num?)?.toInt() ?? 0xFF00695C),
    visibleWhen: Requirement.fromMap(
      map['visibleWhen'] as Map<String, dynamic>?,
    ),
    inspectText: map['inspectText'] as String?,
    onInspect: Effect.fromMap(map['onInspect'] as Map<String, dynamic>?),
    repeatable: map['repeatable'] as bool? ?? true,
  );
}

/// One of the three places the adventure happens in.
class AdventureLocation {
  const AdventureLocation({
    required this.id,
    required this.name,
    required this.description,
    required this.hotspots,
    this.skyColor = const Color(0xFFBBDEFB),
    this.groundColor = const Color(0xFFCDBBA0),
    this.visitFlag,
  });

  final String id;
  final String name;

  /// One or two sentences setting the scene, read aloud where a voice exists.
  final String description;

  final List<Hotspot> hotspots;

  /// The scene is drawn, not photographed — see the note in AdventureScene.
  /// These two colours are its sky and ground.
  final Color skyColor;
  final Color groundColor;

  /// Set the first time the player arrives. Lets dialogue react to where
  /// somebody has already been.
  final String? visitFlag;

  Map<String, dynamic> toMap() => {
    'id': id,
    'name': name,
    'description': description,
    'skyColor': skyColor.toARGB32(),
    'groundColor': groundColor.toARGB32(),
    if (visitFlag != null) 'visitFlag': visitFlag,
    'hotspots': hotspots.map((spot) => spot.toMap()).toList(),
  };

  factory AdventureLocation.fromMap(Map<String, dynamic> map) =>
      AdventureLocation(
        id: map['id'] as String? ?? '',
        name: map['name'] as String? ?? '',
        description: map['description'] as String? ?? '',
        skyColor: Color((map['skyColor'] as num?)?.toInt() ?? 0xFFBBDEFB),
        groundColor: Color((map['groundColor'] as num?)?.toInt() ?? 0xFFCDBBA0),
        visitFlag: map['visitFlag'] as String?,
        hotspots: [
          for (final raw in (map['hotspots'] as List? ?? const []))
            if (raw is Map<String, dynamic>) Hotspot.fromMap(raw),
        ],
      );
}

/// One thing the player can say, and what it does.
class DialogueChoice {
  const DialogueChoice({
    required this.id,
    required this.text,
    this.requires = Requirement.none,
    this.effect = Effect.none,
    this.reply,
    this.goTo,
    this.isDecision = false,
  });

  final String id;

  /// What the player says. Written as the player's own words, not as a menu
  /// label: "I'll fetch it for you", not "Accept quest".
  final String text;

  final Requirement requires;
  final Effect effect;

  /// What the character says back, before moving on.
  final String? reply;

  /// The node to continue to. Null ends the conversation.
  final String? goTo;

  /// Marks a choice that shapes the ending. Recorded in the adventure summary
  /// so the player can see what they decided, and why they got the ending
  /// they got.
  final bool isDecision;

  Map<String, dynamic> toMap() => {
    'id': id,
    'text': text,
    if (!requires.isAlwaysMet) 'requires': requires.toMap(),
    if (!effect.isEmpty) 'effect': effect.toMap(),
    if (reply != null) 'reply': reply,
    if (goTo != null) 'goTo': goTo,
    if (isDecision) 'isDecision': true,
  };

  factory DialogueChoice.fromMap(Map<String, dynamic> map) => DialogueChoice(
    id: map['id'] as String? ?? '',
    text: map['text'] as String? ?? '',
    requires: Requirement.fromMap(map['requires'] as Map<String, dynamic>?),
    effect: Effect.fromMap(map['effect'] as Map<String, dynamic>?),
    reply: map['reply'] as String?,
    goTo: map['goTo'] as String?,
    isDecision: map['isDecision'] as bool? ?? false,
  );
}

/// One thing a character says, with the replies available.
class DialogueNode {
  const DialogueNode({
    required this.id,
    required this.lines,
    this.choices = const [],
    this.requires = Requirement.none,
    this.onEnter = Effect.none,
    this.isKeyMoment = false,
  });

  final String id;

  /// Spoken one panel at a time, so a long speech never becomes a wall.
  final List<String> lines;

  final List<DialogueChoice> choices;

  /// Which node a character opens with is decided by these: the FIRST node in
  /// the character's list whose requirement is met. So the list runs from most
  /// specific to most general, and the last one should always be reachable —
  /// the validator checks that a character can always say something.
  final Requirement requires;

  final Effect onEnter;

  /// Kept in the journal so the player can read it again. A conversation that
  /// carried a request or a clue must never be a thing you can only hear once.
  final bool isKeyMoment;

  Map<String, dynamic> toMap() => {
    'id': id,
    'lines': lines,
    if (choices.isNotEmpty)
      'choices': choices.map((choice) => choice.toMap()).toList(),
    if (!requires.isAlwaysMet) 'requires': requires.toMap(),
    if (!onEnter.isEmpty) 'onEnter': onEnter.toMap(),
    if (isKeyMoment) 'isKeyMoment': true,
  };

  factory DialogueNode.fromMap(Map<String, dynamic> map) => DialogueNode(
    id: map['id'] as String? ?? '',
    lines: [
      for (final line in (map['lines'] as List? ?? const []))
        if (line is String) line,
    ],
    choices: [
      for (final raw in (map['choices'] as List? ?? const []))
        if (raw is Map<String, dynamic>) DialogueChoice.fromMap(raw),
    ],
    requires: Requirement.fromMap(map['requires'] as Map<String, dynamic>?),
    onEnter: Effect.fromMap(map['onEnter'] as Map<String, dynamic>?),
    isKeyMoment: map['isKeyMoment'] as bool? ?? false,
  );
}

/// Somebody to talk to.
class AdventureCharacter {
  const AdventureCharacter({
    required this.id,
    required this.name,
    required this.role,
    required this.locationId,
    required this.nodes,
    this.icon = Icons.person_rounded,
    this.color = const Color(0xFF00695C),
  });

  final String id;
  final String name;

  /// "The potter", "Ammal's grandson". Shown under the name, so a player who
  /// has forgotten who somebody is does not have to remember.
  final String role;

  final String locationId;
  final List<DialogueNode> nodes;
  final IconData icon;
  final Color color;

  Map<String, dynamic> toMap() => {
    'id': id,
    'name': name,
    'role': role,
    'locationId': locationId,
    'icon': adventureIconName(icon),
    'color': color.toARGB32(),
    'nodes': nodes.map((node) => node.toMap()).toList(),
  };

  factory AdventureCharacter.fromMap(Map<String, dynamic> map) =>
      AdventureCharacter(
        id: map['id'] as String? ?? '',
        name: map['name'] as String? ?? '',
        role: map['role'] as String? ?? '',
        locationId: map['locationId'] as String? ?? '',
        icon: adventureIcon(map['icon'] as String?),
        color: Color((map['color'] as num?)?.toInt() ?? 0xFF00695C),
        nodes: [
          for (final raw in (map['nodes'] as List? ?? const []))
            if (raw is Map<String, dynamic>) DialogueNode.fromMap(raw),
        ],
      );
}

