/// One seller in the market.
class MarketStall {
  const MarketStall({
    required this.id,
    required this.name,
    required this.keeperLine,
    required this.itemIds,
    this.soldOutItemIds = const {},
    this.icon = Icons.storefront_rounded,
    this.color = const Color(0xFF8D4004),
  });

  final String id;
  final String name;

  /// What the stallholder says when you walk up.
  final String keeperLine;

  final List<String> itemIds;

  /// Items this stall lists but has run out of. Exactly the mechanism behind
  /// "handle one unavailable item": the player sees it, cannot buy it, and has
  /// to ask about an alternative.
  final Set<String> soldOutItemIds;

  final IconData icon;
  final Color color;

  Map<String, dynamic> toMap() => {
    'id': id,
    'name': name,
    'keeperLine': keeperLine,
    'itemIds': itemIds,
    if (soldOutItemIds.isNotEmpty) 'soldOutItemIds': soldOutItemIds.toList(),
    'icon': adventureIconName(icon),
    'color': color.toARGB32(),
  };

  factory MarketStall.fromMap(Map<String, dynamic> map) => MarketStall(
    id: map['id'] as String? ?? '',
    name: map['name'] as String? ?? '',
    keeperLine: map['keeperLine'] as String? ?? '',
    itemIds: [
      for (final id in (map['itemIds'] as List? ?? const []))
        if (id is String) id,
    ],
    soldOutItemIds: {
      for (final id in (map['soldOutItemIds'] as List? ?? const []))
        if (id is String) id,
    },
    icon: adventureIcon(map['icon'] as String?),
    color: Color((map['color'] as num?)?.toInt() ?? 0xFF8D4004),
  );
}

/// One thing on the shopping list.
class MarketRequest {
  const MarketRequest({
    required this.id,
    required this.label,
    required this.acceptedItemIds,
  });

  final String id;

  /// What was asked for, in the character's words: "something sweet for the
  /// pot". Deliberately not an item id — the player is told what is NEEDED and
  /// works out what satisfies it.
  final String label;

  /// Every item that satisfies this request. More than one wherever it makes
  /// sense, so there is rarely a single correct basket.
  final List<String> acceptedItemIds;

  bool isSatisfiedBy(Set<String> owned) =>
      acceptedItemIds.any(owned.contains);

  Map<String, dynamic> toMap() => {
    'id': id,
    'label': label,
    'acceptedItemIds': acceptedItemIds,
  };

  factory MarketRequest.fromMap(Map<String, dynamic> map) => MarketRequest(
    id: map['id'] as String? ?? '',
    label: map['label'] as String? ?? '',
    acceptedItemIds: [
      for (final id in (map['acceptedItemIds'] as List? ?? const []))
        if (id is String) id,
    ],
  );
}

/// The shopping part of the adventure.
class MarketConfig {
  const MarketConfig({
    required this.startingCoins,
    required this.stalls,
    required this.requests,
    required this.completedFlag,
  });

  /// The purse. Every price and every total is an integer, so the budget never
  /// depends on a rounding rule nobody can see.
  final int startingCoins;

  final List<MarketStall> stalls;
  final List<MarketRequest> requests;

  /// Set once every request is satisfied.
  final String completedFlag;

  Map<String, dynamic> toMap() => {
    'startingCoins': startingCoins,
    'completedFlag': completedFlag,
    'stalls': stalls.map((stall) => stall.toMap()).toList(),
    'requests': requests.map((request) => request.toMap()).toList(),
  };

  factory MarketConfig.fromMap(Map<String, dynamic> map) => MarketConfig(
    startingCoins: (map['startingCoins'] as num?)?.toInt() ?? 0,
    completedFlag: map['completedFlag'] as String? ?? 'market_done',
    stalls: [
      for (final raw in (map['stalls'] as List? ?? const []))
        if (raw is Map<String, dynamic>) MarketStall.fromMap(raw),
    ],
    requests: [
      for (final raw in (map['requests'] as List? ?? const []))
        if (raw is Map<String, dynamic>) MarketRequest.fromMap(raw),
    ],
  );
}

/// One thing the player has noticed.
class Clue {
  const Clue({
    required this.id,
    required this.text,
    required this.source,
    this.icon = Icons.search_rounded,
  });

  final String id;

  /// The clue itself, as a plain observation: "The rope on the west post is
  /// frayed, as if something heavy hung from it."
  final String text;

  /// Where it came from, for the journal: "Told by Kannan".
  final String source;

  final IconData icon;

  Map<String, dynamic> toMap() => {
    'id': id,
    'text': text,
    'source': source,
    'icon': adventureIconName(icon),
  };

  factory Clue.fromMap(Map<String, dynamic> map) => Clue(
    id: map['id'] as String? ?? '',
    text: map['text'] as String? ?? '',
    source: map['source'] as String? ?? '',
    icon: adventureIcon(map['icon'] as String?),
  );
}

/// The mystery of the missing decoration.
class MysteryConfig {
  const MysteryConfig({
    required this.question,
    required this.clues,
    required this.candidateLocationIds,
    required this.solutionLocationId,
    required this.supportingClueIds,
    required this.revealText,
    required this.wrongLocationHint,
    required this.wrongCluesHint,
    required this.solvedFlag,
    required this.decorationItemId,
  });

  /// "Where did the kolam stencil go?"
  final String question;

  /// Exactly three, by the rules of this game.
  final List<Clue> clues;

  /// The places the player may name. Always more than one, or there is no
  /// question to answer.
  final List<String> candidateLocationIds;

  final String solutionLocationId;

  /// The clues that actually justify the answer. The player must pick these to
  /// explain their conclusion — naming the right place by luck is not solving
  /// a mystery.
  final Set<String> supportingClueIds;

  final String revealText;

  /// Shown for a wrong place, and for the right place with the wrong reasons.
  /// Both are nudges, and neither ends the adventure.
  final String wrongLocationHint;
  final String wrongCluesHint;

  final String solvedFlag;

  /// What the player recovers by solving it.
  final String decorationItemId;

  Map<String, dynamic> toMap() => {
    'question': question,
    'clues': clues.map((clue) => clue.toMap()).toList(),
    'candidateLocationIds': candidateLocationIds,
    'solutionLocationId': solutionLocationId,
    'supportingClueIds': supportingClueIds.toList(),
    'revealText': revealText,
    'wrongLocationHint': wrongLocationHint,
    'wrongCluesHint': wrongCluesHint,
    'solvedFlag': solvedFlag,
    'decorationItemId': decorationItemId,
  };

  factory MysteryConfig.fromMap(Map<String, dynamic> map) => MysteryConfig(
    question: map['question'] as String? ?? '',
    clues: [
      for (final raw in (map['clues'] as List? ?? const []))
        if (raw is Map<String, dynamic>) Clue.fromMap(raw),
    ],
    candidateLocationIds: [
      for (final id in (map['candidateLocationIds'] as List? ?? const []))
        if (id is String) id,
    ],
    solutionLocationId: map['solutionLocationId'] as String? ?? '',
    supportingClueIds: {
      for (final id in (map['supportingClueIds'] as List? ?? const []))
        if (id is String) id,
    },
    revealText: map['revealText'] as String? ?? '',
    wrongLocationHint: map['wrongLocationHint'] as String? ?? '',
    wrongCluesHint: map['wrongCluesHint'] as String? ?? '',
    solvedFlag: map['solvedFlag'] as String? ?? 'mystery_solved',
    decorationItemId: map['decorationItemId'] as String? ?? '',
  );
}

/// One place in the courtyard where something can be put.
class PreparationSlot {
  const PreparationSlot({
