/// Getting the courtyard ready.
class PreparationConfig {
  const PreparationConfig({
    required this.slots,
    required this.styles,
    required this.readyFlag,
  });

  final List<PreparationSlot> slots;

  /// **No style is ever wrong.** The brief is explicit and so is this comment:
  /// a cosmetic choice must not be marked incorrect. The slots have rules
  /// because a pot belongs on the fire; the colours do not.
  final List<DecorationStyle> styles;

  /// Set once every slot is filled.
  final String readyFlag;

  Map<String, dynamic> toMap() => {
    'readyFlag': readyFlag,
    'slots': slots.map((slot) => slot.toMap()).toList(),
    'styles': styles.map((style) => style.toMap()).toList(),
  };

  factory PreparationConfig.fromMap(Map<String, dynamic> map) =>
      PreparationConfig(
        readyFlag: map['readyFlag'] as String? ?? 'courtyard_ready',
        slots: [
          for (final raw in (map['slots'] as List? ?? const []))
            if (raw is Map<String, dynamic>) PreparationSlot.fromMap(raw),
        ],
        styles: [
          for (final raw in (map['styles'] as List? ?? const []))
            if (raw is Map<String, dynamic>) DecorationStyle.fromMap(raw),
        ],
      );
}

/// One way the adventure can finish.
class Ending {
  const Ending({
    required this.id,
    required this.title,
    required this.text,
    required this.celebration,
    this.requires = Requirement.none,
    this.color = const Color(0xFF00695C),
    this.icon = Icons.celebration_rounded,
  });

  final String id;
  final String title;

  /// What happened, in a paragraph.
  final String text;

  /// The single line the celebration scene shows.
  final String celebration;

  /// Endings are checked in order and the first match wins, so the more
  /// demanding one must come first. The last ending should always be reachable
  /// — the validator insists on it, otherwise a player could finish the
  /// adventure and be shown nothing.
  final Requirement requires;

  final Color color;
  final IconData icon;

  Map<String, dynamic> toMap() => {
    'id': id,
    'title': title,
    'text': text,
    'celebration': celebration,
    if (!requires.isAlwaysMet) 'requires': requires.toMap(),
    'color': color.toARGB32(),
    'icon': adventureIconName(icon),
  };

  factory Ending.fromMap(Map<String, dynamic> map) => Ending(
    id: map['id'] as String? ?? '',
    title: map['title'] as String? ?? '',
    text: map['text'] as String? ?? '',
    celebration: map['celebration'] as String? ?? '',
    requires: Requirement.fromMap(map['requires'] as Map<String, dynamic>?),
    color: Color((map['color'] as num?)?.toInt() ?? 0xFF00695C),
    icon: adventureIcon(map['icon'] as String?),
  );
}

/// One line of the quest journal.
class QuestStep {
  const QuestStep({
    required this.id,
    required this.title,
    required this.detail,
    required this.doneWhen,
    this.activeWhen = Requirement.none,
    this.hint,
  });

  final String id;
  final String title;

  /// What to do, in a sentence.
  final String detail;

  /// Status is DERIVED from the player's state rather than stored, so the
  /// journal can never drift out of step with the game. There is no way to
  /// mark a step done that did not actually happen.
  final Requirement doneWhen;

  final Requirement activeWhen;

  /// The optional nudge, shown only when the player asks for it.
  final String? hint;

  Map<String, dynamic> toMap() => {
    'id': id,
    'title': title,
    'detail': detail,
    'doneWhen': doneWhen.toMap(),
    if (!activeWhen.isAlwaysMet) 'activeWhen': activeWhen.toMap(),
    if (hint != null) 'hint': hint,
  };

  factory QuestStep.fromMap(Map<String, dynamic> map) => QuestStep(
    id: map['id'] as String? ?? '',
    title: map['title'] as String? ?? '',
    detail: map['detail'] as String? ?? '',
    doneWhen: Requirement.fromMap(map['doneWhen'] as Map<String, dynamic>?),
    activeWhen: Requirement.fromMap(map['activeWhen'] as Map<String, dynamic>?),
    hint: map['hint'] as String?,
  );
}

/// Where the cultural material in an adventure came from, and how far it has
/// been checked.
///
/// The same honesty rule as the cultural packs, for the same reason: a story
/// about somebody's festival that nobody from that place has read is a draft,
/// and the app says so on screen instead of presenting it as established.
class CulturalNote {
  const CulturalNote({
    required this.festival,
    required this.region,
    required this.summary,
    required this.references,
    this.reviewed = false,
  });

  final String festival;
  final String region;

  /// A few true sentences about the festival, from the curated reference pack.
  final String summary;

  final List<String> references;

  final bool reviewed;

  Map<String, dynamic> toMap() => {
    'festival': festival,
    'region': region,
    'summary': summary,
    'references': references,
    'reviewed': reviewed,
  };

  factory CulturalNote.fromMap(Map<String, dynamic> map) => CulturalNote(
    festival: map['festival'] as String? ?? '',
    region: map['region'] as String? ?? '',
    summary: map['summary'] as String? ?? '',
    references: [
      for (final value in (map['references'] as List? ?? const []))
        if (value is String) value,
    ],
    reviewed: map['reviewed'] as bool? ?? false,
  );
}

/// The complete adventure.
class Adventure {
  const Adventure({
    required this.id,
    required this.title,
    required this.intro,
    required this.objective,
    required this.startLocationId,
    required this.locations,
    required this.characters,
    required this.items,
    required this.market,
    required this.mystery,
    required this.preparation,
    required this.quests,
    required this.endings,
    required this.culturalNote,
    this.source = AdventureSource.bundled,
    this.createdAt,
  });

  final String id;
  final String title;

  /// The opening: who you are, where you are, and what is about to happen.
  final String intro;

  /// The one-line objective, always visible in the journal.
  final String objective;

  final String startLocationId;
  final List<AdventureLocation> locations;
  final List<AdventureCharacter> characters;
  final List<AdventureItem> items;
  final MarketConfig market;
  final MysteryConfig mystery;
  final PreparationConfig preparation;
  final List<QuestStep> quests;
  final List<Ending> endings;
  final CulturalNote culturalNote;
  final AdventureSource source;
  final DateTime? createdAt;

  AdventureLocation? location(String id) =>
      locations.where((place) => place.id == id).firstOrNull;

  AdventureCharacter? character(String id) =>
      characters.where((person) => person.id == id).firstOrNull;

  AdventureItem? item(String id) =>
      items.where((thing) => thing.id == id).firstOrNull;

  Clue? clue(String id) =>
      mystery.clues.where((clue) => clue.id == id).firstOrNull;

  Ending? ending(String id) =>
      endings.where((ending) => ending.id == id).firstOrNull;

  List<AdventureCharacter> charactersAt(String locationId) => [
    for (final person in characters)
      if (person.locationId == locationId) person,
  ];

  Adventure copyWith({String? id, AdventureSource? source, DateTime? createdAt}) =>
      Adventure(
        id: id ?? this.id,
        title: title,
        intro: intro,
        objective: objective,
        startLocationId: startLocationId,
        locations: locations,
        characters: characters,
        items: items,
        market: market,
        mystery: mystery,
        preparation: preparation,
        quests: quests,
        endings: endings,
        culturalNote: culturalNote,
        source: source ?? this.source,
        createdAt: createdAt ?? this.createdAt,
      );

  Map<String, dynamic> toMap() => {
    'id': id,
    'title': title,
    'intro': intro,
    'objective': objective,
    'startLocationId': startLocationId,
    'locations': locations.map((place) => place.toMap()).toList(),
    'characters': characters.map((person) => person.toMap()).toList(),
    'items': items.map((thing) => thing.toMap()).toList(),
    'market': market.toMap(),
    'mystery': mystery.toMap(),
    'preparation': preparation.toMap(),
    'quests': quests.map((quest) => quest.toMap()).toList(),
    'endings': endings.map((ending) => ending.toMap()).toList(),
    'culturalNote': culturalNote.toMap(),
    'source': source.name,
    if (createdAt != null) 'createdAt': createdAt!.toIso8601String(),
  };

  factory Adventure.fromMap(Map<String, dynamic> map) => Adventure(
    id: map['id'] as String? ?? '',
    title: map['title'] as String? ?? '',
    intro: map['intro'] as String? ?? '',
    objective: map['objective'] as String? ?? '',
    startLocationId: map['startLocationId'] as String? ?? '',
    locations: [
      for (final raw in (map['locations'] as List? ?? const []))
        if (raw is Map<String, dynamic>) AdventureLocation.fromMap(raw),
    ],
    characters: [
      for (final raw in (map['characters'] as List? ?? const []))
        if (raw is Map<String, dynamic>) AdventureCharacter.fromMap(raw),
    ],
    items: [
      for (final raw in (map['items'] as List? ?? const []))
        if (raw is Map<String, dynamic>) AdventureItem.fromMap(raw),
    ],
    market: MarketConfig.fromMap(
      map['market'] as Map<String, dynamic>? ?? const {},
    ),
    mystery: MysteryConfig.fromMap(
      map['mystery'] as Map<String, dynamic>? ?? const {},
    ),
    preparation: PreparationConfig.fromMap(
      map['preparation'] as Map<String, dynamic>? ?? const {},
    ),
    quests: [
      for (final raw in (map['quests'] as List? ?? const []))
        if (raw is Map<String, dynamic>) QuestStep.fromMap(raw),
    ],
    endings: [
      for (final raw in (map['endings'] as List? ?? const []))
        if (raw is Map<String, dynamic>) Ending.fromMap(raw),
    ],
    culturalNote: CulturalNote.fromMap(
      map['culturalNote'] as Map<String, dynamic>? ?? const {},
    ),
    source: AdventureSource.fromName(map['source'] as String?),
    createdAt: DateTime.tryParse(map['createdAt'] as String? ?? ''),
  );

  String toJson() => jsonEncode(toMap());

  factory Adventure.fromJson(String source) =>
      Adventure.fromMap(jsonDecode(source) as Map<String, dynamic>);
}
